/**
 * @suppress
 */
public object FfiConverterTypePlatformHooks: FfiConverter<PlatformHooks, Long> {
    internal val handleMap = UniffiHandleMap<PlatformHooks>()

    override fun lower(value: PlatformHooks): Long {
        if (value is PlatformHooksImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): PlatformHooks {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return PlatformHooksImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): PlatformHooks {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: PlatformHooks) = 8UL

    override fun write(value: PlatformHooks, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



