/**
 * Errors of the control plane.
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * The configuration is invalid (`detail` names the field).
     */
    class InvalidConfig(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The session start parameters are invalid (bad group id, Lab code over 9999).
     */
    class InvalidStart(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * No stored group has this id.
     */
    class UnknownGroup(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The Demo ride is not available in this build (Phase 1, needs the mesh-sim world).
     */
    class DemoUnavailable(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * The engine thread could not be spawned.
     */
    class ThreadSpawn(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The engine thread panicked while handling the request.
     */
    class Crashed(
        ) : FfiException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
